/// The generated template of `enc`, if there is one.
pub(crate) fn template(enc: Encoding) -> Option<GenFn> {
    Some(match enc {
        Encoding::SHL_asimdshf_R => SHL_asimdshf_R,
        Encoding::SLI_asimdshf_R => SLI_asimdshf_R,
        Encoding::SQSHLU_asimdshf_R => SQSHLU_asimdshf_R,
        Encoding::SQSHL_asimdshf_R => SQSHL_asimdshf_R,
        Encoding::SRI_asimdshf_R => SRI_asimdshf_R,
        Encoding::SRSHR_asimdshf_R => SRSHR_asimdshf_R,
        Encoding::SRSRA_asimdshf_R => SRSRA_asimdshf_R,
        Encoding::SSHLL_asimdshf_L => SSHLL_asimdshf_L,
        Encoding::SSHR_asimdshf_R => SSHR_asimdshf_R,
        Encoding::SSRA_asimdshf_R => SSRA_asimdshf_R,
        Encoding::UQSHL_asimdshf_R => UQSHL_asimdshf_R,
        Encoding::URSHR_asimdshf_R => URSHR_asimdshf_R,
        Encoding::URSRA_asimdshf_R => URSRA_asimdshf_R,
        Encoding::USHLL_asimdshf_L => USHLL_asimdshf_L,
        Encoding::USHR_asimdshf_R => USHR_asimdshf_R,
        Encoding::USRA_asimdshf_R => USRA_asimdshf_R,
        _ => return None,
    })
}
